#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include "h3api.h"
#include "polygon.h"

int main(){
  int found=0;
  for(int res=0; res<=5; res++){
    for(int t=0;t<200000;t++){
      double cx = ((double)rand()/RAND_MAX)*6.0-3.0;
      double cy = ((double)rand()/RAND_MAX)*3.0-1.5;
      double ang = ((double)rand()/RAND_MAX)*M_PI;
      double len = pow(10, ((double)rand()/RAND_MAX)*(-0.5) - 2.0); // .003-.3
      double wid = pow(10, ((double)rand()/RAND_MAX)*(-1.0) - 4.0); // .00001-.001
      LatLng verts[4];
      double ca=cos(ang), sa=sin(ang);
      double xs[4]={-len,len,len,-len}, ys[4]={-wid,-wid,wid,wid};
      for(int i=0;i<4;i++){ verts[i].lat=cy+xs[i]*sa+ys[i]*ca; verts[i].lng=cx+xs[i]*ca-ys[i]*sa; }
      GeoPolygon p={.geoloop={.numVerts=4,.verts=verts},.numHoles=0,.holes=NULL};
      int64_t sz; H3Error e=maxPolygonToCellsSizeExperimental(&p,res,CONTAINMENT_OVERLAPPING,&sz);
      if(e||sz<0||sz>10000) continue;
      H3Index *out=calloc((sz?sz:1)+1000,sizeof(H3Index));
      H3Error e2=polygonToCellsExperimental(&p,res,CONTAINMENT_OVERLAPPING,out);
      int64_t cnt=0; while(out[cnt]) cnt++;
      free(out);
      if(!e2 && cnt>sz){
        fprintf(stderr,"FOUND res=%d sz=%ld cnt=%ld cx=%.17g cy=%.17g ang=%.17g len=%.17g wid=%.17g\n",res,(long)sz,(long)cnt,cx,cy,ang,len,wid);
        for(int i=0;i<4;i++) fprintf(stderr,"v%d %.17g %.17g\n",i,verts[i].lat,verts[i].lng);
        return 0;
      }
    }
    fprintf(stderr,"done res %d\n",res);
  }
  return 1;
}
